import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiArrowLeft, FiCalendar, FiMapPin, FiUsers, FiImage, FiStar, FiAward, FiMessageSquare } from 'react-icons/fi';
import eventService from '../services/eventService';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const PastEventDetailsPage = () => {
  const navigate = useNavigate();
  const [pastEvents, setPastEvents] = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchPastEvents();
  }, []);

  const fetchPastEvents = async () => {
    setLoading(true);
    try {
      const events = await eventService.getPastEvents();
      setPastEvents(events);
      if (events.length > 0) {
        setSelectedEvent(events[0]);
      }
    } catch (error) {
      toast.error('Failed to fetch past events');
      console.error('Error fetching past events:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleEventSelect = (event) => {
    setSelectedEvent(event);
  };

  if (loading) {
    return (
      <div className="past-event-details-page">
        <div className="loading">Loading past events...</div>
      </div>
    );
  }

  if (pastEvents.length === 0) {
    return (
      <div className="past-event-details-page">
        <div className="page-header">
          <h1>Past Event Details</h1>
          <p>Review details of completed events</p>
        </div>

        <div className="empty-state">
          <div className="empty-icon">📭</div>
          <h2>No Past Events Yet</h2>
          <p>There are no completed events to view. Check back later!</p>
          <button 
            className="btn-primary"
            onClick={() => navigate('/')}
          >
            Back to Home
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="past-event-details-page">
      <div className="page-header">
        <h1>Past Event Details</h1>
        <p>Review details of completed events and relive the memories</p>
      </div>

      <div className="past-events-container">
        {/* Events List */}
        <div className="events-list-panel">
          <h2>Past Events ({pastEvents.length})</h2>
          <div className="events-list">
            {pastEvents.map(event => (
              <div 
                key={event._id}
                className={`event-list-item ${selectedEvent?._id === event._id ? 'active' : ''}`}
                onClick={() => handleEventSelect(event)}
              >
                <div className="event-item-header">
                  <h4>{event.title}</h4>
                  <span className="status-badge completed">
                    <FiStar size={16} /> Completed
                  </span>
                </div>
                <p className="event-type">{event.eventType}</p>
                <p className="event-location">📍 {event.location}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Event Details */}
        {selectedEvent && (
          <div className="event-details-panel">
            <div className="details-header">
              <h2>{selectedEvent.title}</h2>
              <span className="completion-badge">
                <FiStar size={20} /> Event Completed
              </span>
            </div>

            <div className="details-content">
              {/* Event Information */}
              <div className="details-section">
                <h3>Event Information</h3>
                <div className="details-grid">
                  <div className="detail-row">
                    <div className="detail-label">
                      <FiCalendar size={18} />
                      <span>Event Type</span>
                    </div>
                    <div className="detail-value">
                      {selectedEvent.eventType?.charAt(0).toUpperCase() + selectedEvent.eventType?.slice(1)}
                    </div>
                  </div>

                  <div className="detail-row">
                    <div className="detail-label">
                      <FiMapPin size={18} />
                      <span>Location</span>
                    </div>
                    <div className="detail-value">{selectedEvent.location}</div>
                  </div>

                  <div className="detail-row">
                    <div className="detail-label">
                      <FiCalendar size={18} />
                      <span>Start Date & Time</span>
                    </div>
                    <div className="detail-value">
                      {new Date(selectedEvent.startDate).toLocaleString()}
                    </div>
                  </div>

                  <div className="detail-row">
                    <div className="detail-label">
                      <FiCalendar size={18} />
                      <span>End Date & Time</span>
                    </div>
                    <div className="detail-value">
                      {new Date(selectedEvent.endDate).toLocaleString()}
                    </div>
                  </div>

                  {selectedEvent.eventType === 'indoor' && selectedEvent.totalSeats && (
                    <div className="detail-row">
                      <div className="detail-label">
                        <FiUsers size={18} />
                        <span>Total Seats</span>
                      </div>
                      <div className="detail-value">{selectedEvent.totalSeats}</div>
                    </div>
                  )}
                </div>
              </div>

              {/* Description */}
              {selectedEvent.description && (
                <div className="details-section">
                  <h3>Description</h3>
                  <p className="description-text">{selectedEvent.description}</p>
                </div>
              )}

              {/* Event Statistics */}
              <div className="details-section">
                <h3>Event Status</h3>
                <div className="status-info">
                  <div className="status-item">
                    <FiStar className="status-icon completed" size={24} />
                    <div className="status-text">
                      <h4>Event Completed</h4>
                      <p>This event has successfully concluded</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Related Links */}
              <div className="details-section">
                <h3>Event Resources</h3>
                <div className="resource-buttons">
                  <button 
                    className="resource-btn"
                    onClick={() => navigate(`/gallery/${selectedEvent._id}`)}
                  >
                    <FiImage size={18} />
                    View Gallery
                  </button>
                </div>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="action-buttons">
              <button 
                className="btn-primary"
                onClick={() => navigate('/past-events')}
              >
                <FiArrowLeft size={18} />
                View All Past Events
              </button>
              <button 
                className="btn-secondary"
                onClick={() => navigate('/')}
              >
                Back to Home
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PastEventDetailsPage;
